    }

    /** Every permission set on the sheet, by action (one not in it keeps the standing rule). */
    public Map<String, String> permissions(String sheetId) {
        Map<String, String> perms = new TreeMap<>();
        jdbc.query("SELECT action_key, roles FROM sheet_permission WHERE sheet_id = ? AND roles IS NOT NULL",
                (RowCallbackHandler) rs -> perms.put(rs.getString("action_key"), rs.getString("roles")), sheetId);
        return perms;
    }

    /** Set the roles that may take `action` (null for blank: the standing rule). */
    public void setPermission(String sheetId, String action, String roles) {
        jdbc.update("MERGE INTO sheet_permission (sheet_id, action_key, roles) KEY (sheet_id, action_key) VALUES (?, ?, ?)",
                sheetId, action, roles);
    }

    /** Whether the user's role may take `action` on the sheet: the roles set for it, else the standing
     *  rule — open, settle, void and close by clerk and steward; reassign and reopen by steward. A
     *  viewer may take none, and no one may on an archived sheet. */
    public boolean allows(String sheetId, String action, String user) {
        if (sheets.archived(sheetId)) return false;
        Role role = role(sheetId, user);
        if (role == Role.VIEWER) return false;
        String roles = permission(sheetId, action);
        if (roles == null) {
            return role == Role.STEWARD || !(action.equals("reassign") || action.equals("reopen"));
        }
        for (String r : roles.split(",")) {
            if (r.trim().equalsIgnoreCase(role.name())) return true;
        }
        return false;
    }
}
}

/** What of a claim's due a person carries, in cents: its own person the due less the holders' parts, a holder their part. */
export function carriedCents(claim: Claim, due: bigint, personId: number): bigint {
  if (claim.personId === personId) return claim.shares.reduce((rest, s) => rest - partCents(due, s.share), due);
  const held = claim.shares.find((s) => s.personId === personId);
  return held === undefined ? 0n : partCents(due, held.share);
}

/** A person's due-total, in cents: the sum of their counted claims' figures, each already rounded —
 *  a settled claim's fixed due, else the figure a statement bound it to, else live at `pctOn(claim)` (the rate that applies to it on its date), plus any late charge and at least `floor`, the rate in force on the claim's
 *  date (at `pct`, the rate in force on the sheet's today, when no `pctOn` is given). 0 with
 *  nothing that counts. With `late`, an overdue claim's late charge is added on top. Null (n/a) when there is no rate today, unless some settled claim keeps a
 *  figure: then it is the sum of the figures there are. With `cap`, it is at most the cap (an n/a one
 *  is not capped). With `personId`, the claims are those the person carries (see `carried`), each
 *  counting what of its due they carry (see `carriedCents`); `pctOn` then gives each claim's rate by its own person. */
export function personDueCents(claims: Claim[], floor: FloorOn, pct: string | undefined, pctOn?: (claim: Claim) => string | undefined, late?: Late, cap?: string | null, personId?: number): bigint | null {
  let sum = 0n;
  let any = false;
  for (const c of counted(claims)) {
    const due = claimDueCents(c, floor, pctOn ? pctOn(c) : pct, late);
    if (due === null) continue;
    sum += personId === undefined ? due : carriedCents(c, due, personId);
    any = true;
  }
  if (pct === undefined && !any) return null;
  return capCents(sum, cap);
}

/** A due-total at most the sheet's `cap` (null or blank: no cap); n/a is not capped. */
export function capCents(due: bigint | null, cap?: string | null): bigint | null {
  if (due === null || cap == null || cap === '') return due;
  const most = hundredths(cap);
  return due > most ? most : due;
}

/** How much a due-total is over the sheet's `cap`: 0 when it is not (or is n/a, or there is no cap). */
export function excessCents(due: bigint | null, cap?: string | null): bigint {
  const capped = capCents(due, cap);
  return due === null || capped === null ? 0n : due - capped;
}

/** Whether a claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by plus its grace
 *  days is before the sheet's today. */
export function overdue(claim: Claim, late: Late): boolean {
  return isOpen(claim) && !claim.deferred && late.today !== '' && overdueFrom(claim, late) < late.today;
}

/** These claims' overdue ones: their count, and their dues with late charges added up in cents (n/a ones skipped).
 *  `pctOn` is the rate that applies to a claim on its date. */
export function overdueFigures(claims: Claim[], late: Late, floor: FloorOn, pctOn: (claim: Claim) => string | undefined): { count: number; cents: bigint } {
  const over = claims.filter((c) => overdue(c, late));
  const cents = over.reduce<bigint>((sum, c) => sum + (claimDueCents(c, floor, pctOn(c), late) ?? 0n), 0n);
  return { count: over.length, cents };
}
