package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimShare;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/**
 * The figures the screen shows — each person's claimed and due-total, the sheet's claimed-total and
 * due-total, and each one's overdue-total and the sheet's — worked out as the screen does, so a change can audit the ones it moved: one ROLLUP
 * line per person whose figures changed (a new person counts as changed), then a TOTALS line when
 * the sheet's totals changed, then, with an alert threshold set, an ALERT line per person (in list
 * order) whose due-total went from at or below it (or none) to above it.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
    private static final BigDecimal HUNDRED = BigDecimal.valueOf(100);

    private final People people;
    private final Claims claims;
    private final Figures figures;
    private final Rates rates;
    private final Sheets sheets;
    private final Audit audit;
    private final Settings settings;

    public Rollup(People people, Claims claims, Figures figures, Rates rates, Sheets sheets, Audit audit, Settings settings) {
        this.people = people;
        this.claims = claims;
        this.figures = figures;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.settings = settings;
    }

    /** The sheet's figures now. A person's due-total is the sum of their counting claims' figures, less
     *  the parts their share holders carry, plus their parts of the counting claims shared with them (a
     *  person's OPEN claims once today reaches their retirement date do not count, unless a statement
     *  binds them; a hold takes nothing out),
     *  n/a when there is no rate today and none has a figure, at most the sheet's cap (n/a is not
     *  capped); the sheet's skips the n/a ones, and its due and overdue totals leave out the single
     *  highest and lowest person's figure when three or more have one. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.onSheet(sheetId);
        Map<Long, Snapshot.PersonFigures> figuresOf = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        List<Person> everyone = people.onSheet(sheetId);
        // Each counting claim's figure (by its own person's grade), for the parts its share holders carry.
        Map<Long, BigDecimal> shared = new java.util.HashMap<>();
        for (Claim claim : all) {
            if (claim.getShares().isEmpty()) continue;
            Person owner = everyone.stream().filter(p -> p.getId() == claim.getPersonId()).findFirst().orElse(null);
            if (owner == null || !owner.counts(claim)) continue;
            BigDecimal figure = figures.due(claim, owner.gradeOn(claim.getDate()));
            if (figure != null) shared.put(claim.getId(), figure);
        }
        for (Person person : everyone) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            BigDecimal overdue = ZERO;
            BigDecimal settled = ZERO;
            int overdueCount = 0;
            boolean any = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId()) continue;
                if (person.countsClaimed(claim) && claim.getCorrects() == null) claimed = claimed.add(claim.getAmount());
                if (!person.counts(claim)) continue;
                String grade = person.gradeOn(claim.getDate());
                BigDecimal figure = figures.due(claim, grade);
                if (figures.overdue(claim, grade)) overdueCount++;
                if (figure != null && claim.getStatus() == ClaimStatus.SETTLED
                        && claim.getCorrects() == null) settled = settled.add(figure);
                if (figure != null) {
                    // Less the parts its share holders carry.
                    BigDecimal kept = figure;
                    for (ClaimShare share : claim.getShares()) kept = kept.subtract(share.partOf(figure));
                    due = due.add(kept);
                    any = true;
                    if (figures.overdue(claim, grade)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            // Their parts of the claims shared with them.
            for (Claim claim : all) {
                BigDecimal figure = shared.get(claim.getId());
                if (figure == null) continue;
                for (ClaimShare share : claim.getShares()) {
                    if (share.personId() != person.getId()) continue;
                    due = due.add(share.partOf(figure));
                    any = true;
                }
            }
            if (!any && rates.pct(sheetId, person.gradeOn(today), today) == null) due = null;
            due = settings.capped(sheetId, due);
            figuresOf.put(person.getId(), new Snapshot.PersonFigures(person.getName(), claimed, due, overdue,
                    settled.subtract(BigDecimal.valueOf(500L * overdueCount)).divide(HUNDRED, 0, RoundingMode.HALF_EVEN)));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) dues.add(due);
            overdues.add(overdue);
        }
        return new Snapshot(figuresOf, claimedTotal, trimmed(dues), trimmed(overdues));
    }

    /** The figures added up, leaving out the single highest and lowest when there are three or more. */
    private static BigDecimal trimmed(List<BigDecimal> figures) {
        List<BigDecimal> sorted = new ArrayList<>(figures);
        sorted.sort(BigDecimal::compareTo);
        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
        return sorted.stream().reduce(ZERO, BigDecimal::add);
    }

    /** Audit the figures that moved between `before` and the sheet now. */
    public void record(String sheetId, Snapshot before, String user) {
        record(sheetId, before, user, audit);
    }

    /** Audit the figures that moved between `before` and the sheet now, to the given audit. */
    public void record(String sheetId, Snapshot before, String user, Audit audit) {
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            Snapshot.PersonFigures was = before.people().get(id);
            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
                    && same(was.overdueTotal(), now.overdueTotal())) return;
            audit.record("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + show(now.claimed())
                    + " due-total=" + show(now.dueTotal()) + " overdue-total=" + show(now.overdueTotal()));
        });
        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())
                || !same(before.overdueTotal(), after.overdueTotal())) {
            audit.record("TOTALS" + prefix + " claimed-total=" + show(after.claimedTotal())
                    + " due-total=" + show(after.dueTotal()) + " overdue-total=" + show(after.overdueTotal()));
        }
        BigDecimal threshold = settings.alertThreshold(sheetId);
        if (threshold == null) return;
        after.people().forEach((id, now) -> {
            Snapshot.PersonFigures was = before.people().get(id);
            if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
                audit.record("ALERT" + prefix + " name=" + now.name() + " due-total=" + show(now.dueTotal()));
            }
        });
    }

    /** Whether a due-total is above the threshold; n/a never is. */
    private static boolean above(BigDecimal dueTotal, BigDecimal threshold) {
        return dueTotal != null && dueTotal.compareTo(threshold) > 0;
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
    }

    private static String show(BigDecimal value) {
        return value == null ? "n/a" : value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.settings;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the settings are saved, so a refused change writes no audit line. A line per setting
 *  set, a dated one ending in its from-date when one was given. */
public class RecordSettingChanged {
    public void record(@Val SettingsChange change, Audit audit) {
        String prefix = "SETTING_CHANGED sheet=" + change.sheetId() + " by=" + change.by();
        if (change.setsClerkLimit()) {
            audit.record(prefix + " key=clerk-limit value="
                    + (change.clerkLimit() != null ? change.clerkLimit().toPlainString() : "")
                    + from(change, Settings.CLERK_LIMIT));
        }
        change.gradeClerkLimit().forEach((grade, limit) ->
                audit.record(prefix + " key=" + Settings.clerkLimitKey(grade) + " value="
                        + (limit != null ? limit.toPlainString() : "") + from(change, Settings.clerkLimitKey(grade))));
        if (change.floor() != null) {
            audit.record(prefix + " key=floor value=" + change.floor().toPlainString() + from(change, Settings.FLOOR));
        }
        if (change.terms() != null) {
            audit.record(prefix + " key=terms value=" + change.terms() + from(change, Settings.TERMS));
        }
        change.gradeTerms().forEach((grade, terms) ->
                audit.record(prefix + " key=terms-" + grade + " value=" + (terms != null ? terms : "")
                        + from(change, Settings.gradeKey(grade))));
        change.gradeGrace().forEach((grade, days) ->
                audit.record(prefix + " key=" + Settings.graceKey(grade) + " value=" + (days != null ? days : "")
                        + from(change, Settings.graceKey(grade))));
        if (change.latePct() != null) {
            audit.record(prefix + " key=late-pct value=" + change.latePct().toPlainString() + from(change, Settings.LATE_PCT));
        }
        if (change.setsPolicyDate()) {
            audit.record(prefix + " key=policy-date value="
                    + (change.policyDate() != null ? change.policyDate().toString() : ""));
        }
        if (change.setsPeriodNumberingFrom()) {
            audit.record(prefix + " key=period-numbering-from value="
                    + (change.periodNumberingFrom() != null ? change.periodNumberingFrom().toString() : ""));
        }
        if (change.setsCap()) {
            audit.record(prefix + " key=cap value=" + (change.cap() != null ? change.cap().toPlainString() : "")
                    + from(change, Settings.CAP));
        }
        if (change.setsProofThreshold()) {
            audit.record(prefix + " key=proof-threshold value="
                    + (change.proofThreshold() != null ? change.proofThreshold().toPlainString() : "")
                    + from(change, Settings.PROOF_THRESHOLD));
        }
        change.gradeProof().forEach((grade, threshold) ->
                audit.record(prefix + " key=" + Settings.proofKey(grade) + " value="
                        + (threshold != null ? threshold.toPlainString() : "") + from(change, Settings.proofKey(grade))));
        if (change.setsNoteThreshold()) {
            audit.record(prefix + " key=note-threshold value="
                    + (change.noteThreshold() != null ? change.noteThreshold().toPlainString() : "")
                    + from(change, Settings.NOTE_THRESHOLD));
        }
        change.perms().forEach((action, roles) ->
                audit.record(prefix + " key=" + Settings.permKey(action) + " value=" + (roles != null ? roles : "")));
        if (change.setsGraceDays()) {
            audit.record(prefix + " key=grace-days value=" + (change.graceDays() != null ? change.graceDays() : ""));
        }
        if (change.setsEntryDate()) {
            audit.record(prefix + " key=entry-date value="
                    + (change.entryDate() != null ? change.entryDate().toString() : ""));
        }
        if (change.setsPot()) {
            audit.record(prefix + " key=pot value=" + (change.pot() != null ? change.pot().toPlainString() : ""));
        }
        if (change.setsParent()) {
            audit.record(prefix + " key=parent value=" + (change.parent() != null ? change.parent() : ""));
        }
        if (change.fiscalStartMonth() != null) {
            audit.record(prefix + " key=fiscal-start-month value=" + change.fiscalStartMonth());
        }
        if (change.setsAlertThreshold()) {
            audit.record(prefix + " key=alert-threshold value="
                    + (change.alertThreshold() != null ? change.alertThreshold().toPlainString() : ""));
        }
        if (change.setsRounding()) {
            audit.record(prefix + " key=rounding value=" + (change.rounding() != null ? change.rounding() : "")
                    + from(change, Settings.ROUNDING));
        }
        if (change.setsReviewThreshold()) {
            audit.record(prefix + " key=review-threshold value="
                    + (change.reviewThreshold() != null ? change.reviewThreshold().toPlainString() : "")
                    + from(change, Settings.REVIEW_THRESHOLD));
        }
        if (change.setsEscalateAfter()) {
            audit.record(prefix + " key=escalate-after value=" + (change.escalateAfter() != null ? change.escalateAfter() : ""));
        }
        if (change.setsReviewSla()) {
            audit.record(prefix + " key=review-sla value=" + (change.reviewSla() != null ? change.reviewSla() : ""));
        }
        if (change.setsScoreMid()) {
            audit.record(prefix + " key=score-mid value=" + (change.scoreMid() != null ? change.scoreMid() : ""));
        }
        if (change.setsScoreHigh()) {
            audit.record(prefix + " key=score-high value=" + (change.scoreHigh() != null ? change.scoreHigh() : ""));
        }
        if (change.setsScoreLog()) {
            audit.record(prefix + " key=score-log value=" + (change.scoreLog() ? "on" : ""));
        }
        if (change.setsMaxOpen()) {
            audit.record(prefix + " key=max-open value=" + (change.maxOpen() != null ? change.maxOpen() : ""));
        }
        if (change.setsProofKinds()) {
            audit.record(prefix + " key=proof-kinds value=" + (change.proofKinds() != null ? change.proofKinds() : ""));
        }
        if (change.setsDefaultGrade()) {
            audit.record(prefix + " key=default-grade value=" + (change.defaultGrade() != null ? change.defaultGrade() : ""));
        }
    }

    /** " from=<date>" when a from-date was given for the key, else nothing. */
    private static String from(SettingsChange change, String key) {
        LocalDate from = change.froms().get(key);
        return from != null ? " from=" + from : "";
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';
import { hundredths } from '../rates/useRates';

/** A pool's member as the server sends it: the person (or, for a member that is another pool, null
 *  and that pool's name in `pool`), their share (two decimals) and whether they are retired (a
 *  retirement date set, whatever the date), and their cut of the pool's pot (two decimals; null when
 *  the pool is unbalanced or has no pot, or the member is out of their dates), their from- and
 *  to-dates (null when none) and whether those include the sheet's today (a member out of them is
 *  left out of the pool). A pool that is a member of none has the sheet's pot; one that is a member
 *  of another has its cut there. `cuts` is their cut at the end of each period whose to-date is on or
 *  before the sheet's today, or the cut fixed when a closed period was closed (whatever its to-date),
 *  by period name in the periods' order (null when they had none then). */
export type PoolMember = {
  personId: number | null;
  name: string;
  share: string;
  retired: boolean;
  cut: string | null;
  pool: string | null;
  from: string | null;
  to: string | null;
  current: boolean;
  cuts: Record<string, string | null>;
};

/** A pool as the server sends it: its name, its members in the order added, the total of their
 *  shares (two decimals; a retired member's counts as given), whether it is exactly 100.00 and
 *  whether it is a crew's (listed after the pools: the lead and the members at equal shares of
 *  100.00, the remainder on the lead; its members come from the crew, not the pool's form). */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean; crew: boolean };

/** A share percent: up to two decimals. */
export const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

export const poolsKey = (sheet: string) => ['sheet', sheet, 'pools'] as const;

/** The sheet's pools, in the order added, re-read whenever the sheet is loaded. */
export function usePools(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(poolsKey(sheet), asOf),
    queryFn: () => getJson<Pool[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/pools`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The cuts of the person members of `pools` (just `personId`'s when given) added up, in cents; a
 *  pool member that is another pool, or a member with no cut, adds nothing. */
export function cutTotalCents(pools: Pool[], personId?: number): bigint {
  return pools
    .flatMap((p) => p.members)
    .filter((m) => m.personId !== null && m.cut !== null && (personId === undefined || m.personId === personId))
    .reduce((sum, m) => sum + hundredths(m.cut as string), 0n);
}

